import uuid
from datetime import datetime

from sqlalchemy import BigInteger, DateTime, Identity, Integer, Uuid, func
from sqlalchemy.orm import Mapped, mapped_column

# BIGINT on PostgreSQL. SQLite only auto-generates values for ``INTEGER PRIMARY KEY``,
# so the isolated SQLite unit tests fall back to INTEGER.
BigIntType = BigInteger().with_variant(Integer, "sqlite")


class UUIDPrimaryKeyMixin:
    id: Mapped[uuid.UUID] = mapped_column(Uuid, primary_key=True, default=uuid.uuid4)


class BigIntPrimaryKeyMixin:
    """Auto-generated BIGINT primary key ``id`` for high-volume, read-heavy tables.

    Rendered as ``GENERATED BY DEFAULT AS IDENTITY``. ``BY DEFAULT`` (not ``ALWAYS``)
    is deliberate: explicit ids can still be inserted when migrating legacy data.

    The fresh-table identity sequence starts at 1. After loading legacy rows with
    explicit ids, the migration must advance the sequence from the loaded maximum,
    rather than hard-coding a guessed start value::

        SELECT setval(
            pg_get_serial_sequence('applicants', 'id'),
            COALESCE((SELECT MAX(id) FROM applicants), 0) + 1,
            false
        );

    Apply the same statement for each migrated identity table. The next generated
    id is then exactly ``MAX(id) + 1`` (or 1 when the table is empty).
    """

    id: Mapped[int] = mapped_column(BigIntType, Identity(), primary_key=True)


class TimestampMixin:
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), nullable=False
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        server_default=func.now(),
        onupdate=func.now(),
        nullable=False,
    )


class SoftDeleteMixin:
    deleted_at: Mapped[datetime | None] = mapped_column(
        DateTime(timezone=True), nullable=True
    )
